CREATE DATABASE IF NOT EXISTS tiket_konser CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tiket_konser;
CREATE TABLE IF NOT EXISTS konser (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(120) NOT NULL, lokasi VARCHAR(160) NOT NULL, tanggal DATETIME NOT NULL, harga INT UNSIGNED NOT NULL, stok INT UNSIGNED NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pemesanan (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kode VARCHAR(32) NOT NULL UNIQUE, konser_id INT UNSIGNED NOT NULL, nama VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL, jumlah TINYINT UNSIGNED NOT NULL, total INT UNSIGNED NOT NULL, dibuat_pada TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (konser_id) REFERENCES konser(id)) ENGINE=InnoDB;
INSERT INTO konser VALUES (1,'Senandung Senja','Taman Musik, Bandung','2027-06-12 16:00:00',150000,150),(2,'Malam Berirama','Hall Harmoni, Jakarta','2027-07-03 19:00:00',225000,100),(3,'Suara Kota','Arena Kreatif, Yogyakarta','2027-08-21 18:30:00',175000,200) ON DUPLICATE KEY UPDATE id=VALUES(id);
CREATE TABLE IF NOT EXISTS admin (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 username VARCHAR(50) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL,
 dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
